import { useEffect, useState } from 'react';
import Navbar from '../components/Navbar';
import Footer from '../components/Footer';
import SectionReveal from '../components/SectionReveal';
import WarpedDataWall, { generateDataWall } from '../components/WarpedDataWall';
import { Terminal as TerminalIcon, Network, Shield, Bot, Database } from 'lucide-react';

const CommandCategory = ({ title, icon: Icon, description, commands }: any) => (
  <div className="mb-24">
    <div className="flex items-center gap-4 mb-8 border-b border-white/10 pb-6">
      <div className="w-12 h-12 bg-white/5 rounded-full flex items-center justify-center border border-white/10">
        <Icon size={20} className="text-white" />
      </div>
      <div>
        <h2 className="text-[28px] font-serif text-[#F5F5F3]">{title}</h2>
        <p className="text-[14px] text-white/50 font-mono mt-1 uppercase tracking-widest">{description}</p>
      </div>
    </div>

    <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
      {commands.map((cmd: any) => (
        <div key={cmd.name} className="bg-[#111] border border-white/10 p-8 flex flex-col group hover:border-white/20 transition-colors">
          <div className="font-mono text-[16px] text-white font-bold mb-4 flex items-center gap-3">
            <span className="text-white/40">$</span> aura {cmd.name}
          </div>
          <p className="text-[15px] text-[#AAA] leading-[1.6] mb-6 flex-1">
            {cmd.desc}
          </p>
          {cmd.flags && (
            <div className="mt-auto pt-6 border-t border-white/5 flex flex-col gap-2">
              <span className="text-[10px] font-mono text-white/40 uppercase tracking-widest">Options / Args</span>
              <code className="text-[12px] font-mono text-white/60 bg-black px-3 py-2 border border-white/10">
                {cmd.flags}
              </code>
            </div>
          )}
        </div>
      ))}
    </div>
  </div>
);

export default function Docs() {
  const [dataRows, setDataRows] = useState<string[]>([]);

  useEffect(() => {
    setDataRows(generateDataWall(100)); 
  }, []);

  const categories = [
    {
      title: "Core Commands",
      icon: TerminalIcon,
      description: "System Initialization & Configuration (Open Source)",
      commands: [
        { name: "init", desc: "Initialize Aura in the current Git repository. Sets up the hidden .git/aura internal storage, installs the parasitic Git hooks, and prepares the SQLite cache." },
        { name: "status", desc: "View the current gatekeeper status, active dev modes, and local semantic checkpoint history." },
        { name: "config", desc: "Manage global Aura configurations (e.g. telemetry opt-out, setting API keys non-interactively).", flags: "<action>" }
      ]
    },
    {
      title: "AI Orchestration",
      icon: Bot,
      description: "Planning & Execution (Open Source)",
      commands: [
        { name: "plan", desc: "Native GSD Orchestration. Synthesizes a massive natural language request into atomic XML plans by querying the local Merkle-Graph for blast radius.", flags: "<prompt>" },
        { name: "execute", desc: "Wave Execution runner. Iterates through generated plans, spinning up fresh, isolated AI context windows for each atomic step." },
        { name: "handover", desc: "Generates a dense, token-optimized XML context block containing the latest logic hashes and intents to pass to another agent.", flags: "<agent>" }
      ]
    },
    {
      title: "Semantic Time Machine",
      icon: Network,
      description: "AST Tracking & Reverts (Open Source)",
      commands: [
        { name: "rewind", desc: "Surgically revert a specific function or class to its previous state. The --amnesia flag wipes the local AI's memory of the hallucination.", flags: "<identifier> <file_path> [--amnesia]" },
        { name: "audit", desc: "Semantic Audit. Scans Git history to identify any commits that bypassed the gatekeeper using --no-verify, flagging unverified AI logic injections." },
        { name: "request-access", desc: "Sovereign Allowlist. A node-level protocol to authorize legitimate high-entropy logic (like Auth headers) without compromising global security rules.", flags: "<identifier>" }
      ]
    },
    {
      title: "Aura Enterprise",
      icon: Shield,
      description: "Proprietary Cloud & Team Features (BSL)",
      commands: [
        { name: "verify-env", desc: "The Production Gatekeeper. Simulates a deployment by projecting the local Merkle-Graph against a target environment's constraint schema.", flags: "<target_env>" },
        { name: "generate-stubs", desc: "Executes Zero-Trust Virtual Workspaces. Uses local LLMs to dynamically strip highly proprietary algorithms and replace them with type-safe mock stubs." },
        { name: "arbitrate", desc: "Trigger Autonomous Arbitration. Resolves complex semantic merge conflicts across team branches by synthesizing a logic-aware patch.", flags: "<file_path>" },
        { name: "dashboard", desc: "Spins up the React-based Web Dashboard to visualize cross-repo Semantic AI History and Team Merkle-Graphs." }
      ]
    }
  ];

  return (
    <div className="min-h-screen bg-[#050505] text-[#F5F5F3] font-sans overflow-x-hidden">
      <Navbar />

      <main className="pt-32 pb-32">
        {/* Header Section */}
        <section className="px-8 md:px-16 lg:px-24 w-full pt-16 mb-32 relative overflow-hidden">
          <div className="absolute inset-0 z-0 opacity-20 pointer-events-none">
            {dataRows.length > 0 && <WarpedDataWall rows={dataRows} />}
          </div>
          <div className="relative z-10 w-full flex flex-col gap-10">
            <SectionReveal>
              <div className="text-[11px] font-mono uppercase tracking-[0.2em] text-white/50 mb-8">
                Documentation / Reference
              </div>

              <h1 className="text-[40px] md:text-[72px] lg:text-[90px] font-serif leading-[0.95] tracking-tight text-[#F5F5F3] mb-12">
                CLI Command<br/>
                <span className="italic text-[#888]">Reference.</span>
              </h1>

              <div className="border-t border-white/10 pt-12">
                <p className="text-[20px] md:text-[24px] text-[#AAA] leading-[1.6] font-medium max-w-4xl">
                  Aura is controlled via a single, high-performance Rust binary. Explore the command registry below to understand how to interact with the Semantic Physics Engine, Local Vault, and AI Orchestrators.
                </p>
              </div>
            </SectionReveal>
          </div>
        </section>

        {/* Command Registry */}
        <section className="px-8 md:px-16 lg:px-24 w-full">
          <SectionReveal>
            <div className="w-full">
              {categories.map(category => (
                <CommandCategory key={category.title} {...category} />
              ))}
            </div>
          </SectionReveal>

          {/* Internal Git Hooks Warning */}
          <SectionReveal>
            <div className="mt-24 p-12 bg-[#0A0A0A] border-l-4 border-red-900/50">
               <h3 className="text-xl font-serif text-white mb-4 flex items-center gap-3">
                 <Database size={20} className="text-white/40"/> Internal Git Hooks
               </h3>
               <p className="text-[15px] text-[#AAA] leading-[1.6]">
                 Note: Aura operates heavily through native Git hooks (`pre-commit`, `commit-msg`, `post-commit`). Commands such as <code>capture-context</code>, <code>inject-trailer</code>, and <code>persist-checkpoint</code> are executed automatically by the daemon during standard Git operations. You do not need to run these manually unless debugging the engine.
               </p>
            </div>
          </SectionReveal>
        </section>
      </main>

      <Footer />
    </div>
  );
}
